<?php
namespace KTickets;
if (!defined('ABSPATH')) { exit; }

final class UI {
    public static function boot(): void {
        add_action('admin_menu',[self::class,'menu']);
        add_action('admin_notices',[self::class,'notices']);
        add_action('admin_post_ktickets_setup',[self::class,'setup']);
        add_action('admin_post_ktickets_settings',[self::class,'save_settings']);
        add_action('admin_post_ktickets_project',[self::class,'save_project']);
        add_action('admin_post_ktickets_cleanup',static function () { self::guard('manage_ktickets_settings');Service::cleanup();wp_safe_redirect(admin_url('admin.php?page=ktickets-settings'));exit; });
        add_action('template_redirect',[self::class,'standalone'],0);
        add_shortcode('ktickets_form',static fn($a)=>self::form(shortcode_atts(['project'=>'soft1-code-assistant'],$a),false));
        add_shortcode('ktickets_privacy_form',static fn($a)=>self::form(shortcode_atts(['project'=>'soft1-code-assistant'],$a),true));
        add_shortcode('ktickets_portal',static fn()=>self::portal());
        add_filter('wp_sitemaps_posts_query_args',[self::class,'exclude'],10,2);
        add_filter('wpseo_exclude_from_sitemap_by_post_ids',static fn($ids)=>array_unique(array_merge($ids,self::pages())));
        add_action('pre_get_posts',static function ($q) { if (!is_admin() && ($q->is_search() || $q->is_feed())) { $q->set('post__not_in',array_unique(array_merge((array)$q->get('post__not_in'),self::pages()))); } });
        add_filter('rest_page_query',static function ($args) { $args['post__not_in']=array_unique(array_merge((array)($args['post__not_in']??[]),self::pages()));return $args; });
    }
    public static function pages(): array { $s=Store::settings();return array_values(array_filter(array_map('intval',[$s['form_page'],$s['privacy_page'],$s['portal_page']]))); }
    public static function exclude(array $args,string $type): array { if ($type==='page') { $args['post__not_in']=array_merge((array)($args['post__not_in']??[]),self::pages()); }return $args; }
    public static function standalone(): void {
        if (!is_singular('page')) { return; } $post=get_post();if (!$post) { return; }
        $content=$post->post_content;
        if (!has_shortcode($content,'ktickets_portal') && !has_shortcode($content,'ktickets_form') && !has_shortcode($content,'ktickets_privacy_form')) { return; }
        if (!defined('DONOTCACHEPAGE')) { define('DONOTCACHEPAGE',true); }
        do_action('litespeed_control_set_nocache','Kourentzes Tickets private surface');
        nocache_headers();header('Cache-Control: no-store, private, max-age=0');header('Referrer-Policy: no-referrer');header('X-Robots-Tag: noindex, nofollow, noarchive');header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");
        ?><!doctype html><html lang="<?php echo esc_attr(get_bloginfo('language')); ?>"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title><?php echo esc_html($post->post_title); ?></title><link rel="stylesheet" href="<?php echo esc_url(plugins_url('assets/tickets.css',KTICKETS_FILE)); ?>"></head><body><main class="ktickets"><h1><?php echo esc_html($post->post_title); ?></h1><?php
        // Render only ticket shortcodes, never arbitrary page/theme blocks or third-party shortcode callbacks.
        preg_match_all('/\[(ktickets_form|ktickets_privacy_form|ktickets_portal)\b([^\]]*)\]/',$content,$matches,PREG_SET_ORDER);
        foreach ($matches as $match) {
            $attrs=shortcode_parse_atts($match[2]);$attrs=is_array($attrs)?$attrs:[];
            echo $match[1]==='ktickets_portal'?self::portal():self::form(['project'=>$attrs['project']??'soft1-code-assistant'],$match[1]==='ktickets_privacy_form'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- escaped render methods.
        }
        ?></main><script src="<?php echo esc_url(plugins_url('assets/tickets.js',KTICKETS_FILE)); ?>" defer></script></body></html><?php exit;
    }
    private static function config(string $mode, array $extra=[]): string {
        $strings=[
            'working'=>__('Working…','kourentzes-tickets'),'error'=>__('The request failed. Retry the same submission.','kourentzes-tickets'),
            'saved'=>__('Request received. Save your private link now. There are no email notifications; return here to check for replies. Lost links cannot be recovered.','kourentzes-tickets'),
            'pending'=>__('This request is awaiting review.','kourentzes-tickets'),'copy'=>__('Copy private link','kourentzes-tickets'),'download'=>__('Download access file','kourentzes-tickets'),
            'copied'=>__('Copied.','kourentzes-tickets'),'needKey'=>__('Open your saved private link to access this ticket.','kourentzes-tickets'),
            'staff'=>__('Staff','kourentzes-tickets'),'guest'=>__('You','kourentzes-tickets'),'internal'=>__('Internal note','kourentzes-tickets'),
            'closed'=>__('Closed: read-only. Use the new request link to contact us again.','kourentzes-tickets'),'success'=>__('Saved.','kourentzes-tickets'),
            'deleteConfirm'=>__('Permanently delete this ticket and every related message, key and session?','kourentzes-tickets'),
            'rotateConfirm'=>__('Replace the private key and revoke every existing guest session?','kourentzes-tickets'),
            'status'=>__('Status','kourentzes-tickets'),'retention'=>__('Scheduled deletion','kourentzes-tickets'),'noPurge'=>__('No closure retention countdown yet.','kourentzes-tickets'),
            'expired'=>__('The pending submission expired. Reload to start again.','kourentzes-tickets'),
        ];
        return ' data-kt-config="'.esc_attr(wp_json_encode(array_merge(['mode'=>$mode,'api'=>rest_url('ktickets/v1/'),'nonce'=>wp_create_nonce('wp_rest'),'strings'=>$strings],$extra))).'"';
    }
    public static function form(array $attrs, bool $privacy): string {
        $s=Store::settings();
        try { $project=Service::project((string)$attrs['project']);$allowed=(array)json_decode($project['allowed_categories'],true); } catch (\Throwable $e) { return '<p>'.esc_html__('This ticket project is unavailable.','kourentzes-tickets').'</p>'; }
        if ($privacy && !in_array('privacy',$allowed,true)) { return '<p>'.esc_html__('Privacy intake is unavailable for this project.','kourentzes-tickets').'</p>'; }
        ob_start();
        ?><section class="kt-surface"<?php echo self::config('form',['project'=>$attrs['project'],'privacy'=>$privacy]); ?>><p><?php esc_html_e('Do not include passwords, access tokens, databases or unnecessary personal data about others. A technical report does not create a support contract or guarantee a solution.','kourentzes-tickets'); ?></p><p><?php esc_html_e('No email or account is required. Save the private link after submission and return to check for replies.','kourentzes-tickets'); ?></p><?php
        if (!$s['enabled'] || !Security::secure()) { ?><p role="status"><?php esc_html_e('New submissions are temporarily disabled.','kourentzes-tickets'); ?></p></section><?php return ob_get_clean(); }
        ?><form class="kt-create"><label><?php esc_html_e('Subject (5–160 characters)','kourentzes-tickets'); ?><input name="subject" minlength="5" maxlength="160" required></label><?php if (!$privacy) { ?><label><?php esc_html_e('Category','kourentzes-tickets'); ?><select name="category"><?php self::options(array_intersect_key(['technical'=>'Technical issue','suggestion'=>'Suggestion','other'=>'Other'],array_flip($allowed))); ?></select></label><?php } else { ?><label><?php esc_html_e('Request type','kourentzes-tickets'); ?><select name="request_type"><?php self::options(array_combine(Service::TYPES,Service::TYPES)); ?></select></label><?php } ?><label><?php esc_html_e('Description (20–20,000 characters; plain text)','kourentzes-tickets'); ?><textarea name="body" minlength="20" maxlength="20000" rows="10" required></textarea></label><label><?php esc_html_e('Alias (optional)','kourentzes-tickets'); ?><input name="alias" maxlength="80" autocomplete="off"></label><?php if (!$privacy) { foreach (['plugin_version'=>'Plugin version','soft1_version'=>'Soft1 version','runtime'=>'Execution environment'] as $name=>$label) { ?><label><?php echo esc_html__($label,'kourentzes-tickets'); ?><input name="<?php echo esc_attr($name); ?>" maxlength="160"></label><?php } } ?><div class="kt-honey" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="kt-check"><input type="checkbox" name="acknowledge" required><?php esc_html_e('I understand that the private link is my access key and cannot be recovered if lost.','kourentzes-tickets'); ?></label><p><a href="<?php echo esc_url($s['policy_url']); ?>" rel="noreferrer"><?php esc_html_e('Privacy notice','kourentzes-tickets'); ?></a><?php if ($s['terms_url']) { ?> · <a href="<?php echo esc_url($s['terms_url']); ?>" rel="noreferrer"><?php esc_html_e('Terms','kourentzes-tickets'); ?></a><?php } ?></p><button type="submit" disabled><?php esc_html_e('Submit private request','kourentzes-tickets'); ?></button></form><div class="kt-result" role="status" aria-live="polite" tabindex="-1"></div><?php if (!$privacy && $s['privacy_page']) { ?><p><a href="<?php echo esc_url(get_permalink((int)$s['privacy_page'])); ?>"><?php esc_html_e('Privacy / personal data request','kourentzes-tickets'); ?></a></p><?php } ?></section><?php return ob_get_clean();
    }
    public static function portal(): string {
        ob_start();$s=Store::settings();?><section class="kt-surface"<?php echo self::config('portal'); ?>><p><?php esc_html_e('This private link grants access to the conversation. No email notifications are sent. Do not share the link.','kourentzes-tickets'); ?></p><div class="kt-result" role="status" aria-live="polite" tabindex="-1"></div><div class="kt-conversation"></div><button type="button" class="kt-older" hidden><?php esc_html_e('Load older messages','kourentzes-tickets'); ?></button><form class="kt-reply" hidden><label><?php esc_html_e('Reply (plain text)','kourentzes-tickets'); ?><textarea name="body" maxlength="20000" rows="6" required></textarea></label><button type="submit"><?php esc_html_e('Send reply','kourentzes-tickets'); ?></button><button type="button" class="kt-privacy-request"><?php esc_html_e('Submit this message as a privacy / deletion request','kourentzes-tickets'); ?></button></form><button type="button" class="kt-refresh" hidden><?php esc_html_e('Refresh conversation','kourentzes-tickets'); ?></button> <button type="button" class="kt-logout" hidden><?php esc_html_e('End this ticket session','kourentzes-tickets'); ?></button><p><a href="<?php echo esc_url(get_permalink((int)$s['form_page'])); ?>"><?php esc_html_e('New request','kourentzes-tickets'); ?></a> · <a href="<?php echo esc_url(get_permalink((int)$s['privacy_page'])); ?>"><?php esc_html_e('Privacy request','kourentzes-tickets'); ?></a></p></section><?php return ob_get_clean();
