        $s=Store::settings();$error=get_option('ktickets_migration_error');
        if (!$s['owner'] || !$s['enabled'] || !is_ssl() || $error) { ?><div class="notice notice-warning"><p><?php esc_html_e('Kourentzes Tickets: complete owner setup and live cache/privacy verification before enabling public submissions. HTTPS is required.','kourentzes-tickets'); ?> <?php echo esc_html($error?:''); ?></p></div><?php }
